        empties=[i for i in range(9) if b[i]==0]
        if not empties:
            return None if mode=='S' else 'O'
        if turn==1:
            for i in empties:
                nb=list(b); nb[i]=1; nb=tuple(nb)
                if line(nb,1): return 'X'
            children=[(i,solve(tuple(list(b[:i])+(1,)+list(b[i+1:])),2)) for i in empties]
